<?php declare(strict_types=1); namespace App\Services; use Core\Database\DatabaseManager; use Core\Support\Str; class SlugService { public function __construct(private readonly DatabaseManager $db) { } public function generate(string $value, ?string $uniqueInTable = null, ?string $column = 'slug', int|string|null $ignoreId = null): string { $base = Str::slug($value); if ($base === '') { $base = Str::random(8); } if ($uniqueInTable === null) { return $base; } $slug = $base; $suffix = 1; while ($this->exists($uniqueInTable, $column ?? 'slug', $slug, $ignoreId)) { $suffix++; $slug = $base . '-' . $suffix; } return $slug; } private function exists(string $table, string $column, string $slug, int|string|null $ignoreId): bool { $query = $this->db->connection()->table($table)->where($column, $slug); if ($ignoreId !== null) { $query->where('id', '!=', $ignoreId); } return $query->exists(); } } 